const IMG_DIR = '/pkgFood/images/dish/'

function salesNum(s) {
  const m = String(s || '').match(/^([\d.]+)/)
  return m ? parseFloat(m[1]) : 0
}

const SHOPS = SHOP_ROWS.map((r, i) => ({
  i,
  name: r[0],
  inside: r[1] === 'in',
  zone: r[2],
  kind: r[3],
  sales: r[4],
  sv: salesNum(r[4]),
  score: r[5],
  dist: r[6],
  minp: r[7],
  ship: r[8],
  dishes: [],
  reviews: [],
  n: 0,
}))

const DISHES = DISH_ROWS.map((r, i) => {
  const shop = SHOPS[r[1]]
  const d = {
    i,
    n: r[0],
    shop: r[1],
    shopName: shop ? shop.name : '',
    zone: shop ? shop.zone : '',
    inside: shop ? shop.inside : false,
    cat: r[2],
    sold: r[3],
    sv: salesNum(r[3]),
    img: r[4] ? IMG_DIR + r[4] + '.jpg' : '',
    sig: !!r[5],
    desc: DESCS[r[6]] || '',
    ai: !!r[7],
  }
  if (shop) { shop.dishes.push(d); shop.n += 1 }
  return d
})

// 菜品月售不可能比整店月售还高：这类数字是快照时串行的，两个数对不上就都不显示。
// 整店月售缺失的店，单品超过 1000 也按不可信处理（单个档口一天卖不了 30 份以上同一道菜）。
DISHES.forEach((d) => {
  const s = SHOPS[d.shop]
  const cap = (s && s.sv) ? s.sv : 1000
  if (d.sv > cap) { d.odd = true; d.sv = 0; d.sold = '' }
})

REV_ROWS.forEach((r) => {
  const shop = SHOPS[r[0]]
  if (shop) shop.reviews.push({ u: r[1], d: r[2], x: r[3], rec: r[4], t: r[5] })
})

// 每店的好评/中评/差评条数与好评占比：列表里直接显示，不让页面重复算
SHOPS.forEach((s) => {
  const c = { good: 0, mid: 0, bad: 0 }
  s.reviews.forEach((r) => {
    if (r.t === '好评') c.good += 1
    else if (r.t === '中评') c.mid += 1
    else if (r.t === '差评') c.bad += 1
  })
  const rated = c.good + c.mid + c.bad
  s.rc = c
  s.revN = s.reviews.length
  s.rated = rated
  s.goodPct = rated ? Math.round((c.good / rated) * 100) : 0
})

const CAT_ORDER = ['招牌主食', '主食', '配菜/加料', '饮品', '小食', '烤串', '套餐']
const catCount = {}
DISHES.forEach((d) => { catCount[d.cat] = (catCount[d.cat] || 0) + 1 })
const CATS = CAT_ORDER.filter((c) => catCount[c]).map((c) => ({ k: c, n: catCount[c] }))
Object.keys(catCount).forEach((c) => {
  if (CATS.every((x) => x.k !== c)) CATS.push({ k: c, n: catCount[c] })
})

// 销量榜：同名菜只留卖得最好的那家，避免同一道菜刷满一屏
const bestOf = {}
DISHES.forEach((d) => {
  // 只让有实拍图的进榜：没图的排在最前面，一屏全是占位块，榜也就没意义了
  if (!d.sv || !d.img) return
  const cur = bestOf[d.n]
  if (!cur || d.sv > cur.sv || (d.sv === cur.sv && d.img && !cur.img)) bestOf[d.n] = d
})
const BOARD = Object.keys(bestOf)
  .map((k) => bestOf[k])
  .sort((a, b) => (b.sv - a.sv) || (b.sig - a.sig))
  .slice(0, 60)

const STATS = {
  dishes: DISHES.length,
  shops: SHOPS.length,
  insideShops: SHOPS.filter((s) => s.inside).length,
  outShops: SHOPS.filter((s) => !s.inside).length,
  reviews: REV_ROWS.length,
  revGood: REV_ROWS.filter((r) => r[5] === '好评').length,
  revMid: REV_ROWS.filter((r) => r[5] === '中评').length,
  revBad: REV_ROWS.filter((r) => r[5] === '差评').length,
  revRec: REV_ROWS.filter((r) => r[4]).length,
  withImg: DISHES.filter((d) => d.img).length,
  aiImg: DISHES.filter((d) => d.ai).length,
  odd: DISHES.filter((d) => d.odd).length,
}

module.exports = { SOURCE, SHOPS, DISHES, CATS, BOARD, STATS }
